    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 70-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Trochanteric region. This is classified as Vancouver A. What is the most appropriate management?', '["Revision arthroplasty with proximal femoral replacement", "Nonoperative management with protected weight-bearing", "Revision arthroplasty with a longer stem", "ORIF with plates and cables", "Nonoperative or cerclage wires if widely displaced"]'::jsonb, 4, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver A fractures occur Trochanteric region and are best managed by Nonoperative or cerclage wires if widely displaced.'),
    (v_topic_id, 'A 87-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding myocardial infarction, which of the following is most accurate in this setting?', '["Within the first 30 days postoperatively", "It is a rare complication seen almost exclusively in young patients", "It is completely preventable with prophylactic antibiotics", "It is solely caused by the type of implant bearing surface used", "It only occurs after the 3-month postoperative mark"]'::jsonb, 0, 'Myocardial infarction is a known systemic complication following major joint arthroplasty. Specifically, it is within the first 30 days postoperatively. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 73-year-old patient with end-stage post-traumatic ankle osteoarthritis is seeking surgical intervention. Which of the following patient profiles is considered the MOST ideal candidate for a total ankle arthroplasty (TAA) rather than an ankle arthrodesis?', '["An older, lower-demand patient with relatively good bone stock and normal hindfoot alignment", "A patient with marked, uncorrectable varus deformity of the hindfoot", "A patient with severe avascular necrosis of the talus", "A patient with a history of deep soft-tissue infection in the affected ankle", "A young, high-demand laborer with a physically strenuous job"]'::jsonb, 0, 'Total ankle arthroplasty is generally preferred for older, lower-demand individuals who wish to preserve range of motion. Contraindications typically include high physical demand, severe malalignment, prior infection, and poor bone stock (e.g., extensive AVN of the talus). Arthodesis remains the gold standard for high-demand patients.'),
    (v_topic_id, 'A 77-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding delirium, which of the following is most accurate in this setting?', '["It is a rare complication seen almost exclusively in young patients", "It is solely caused by the type of implant bearing surface used", "Common in elderly patients, associated with narcotic use and hypoxia", "It is completely preventable with prophylactic antibiotics", "It only occurs after the 3-month postoperative mark"]'::jsonb, 2, 'Delirium is a known systemic complication following major joint arthroplasty. Specifically, it is common in elderly patients, associated with narcotic use and hypoxia. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 72-year-old male undergoes a total hip arthroplasty via a standard anterolateral approach. Postoperatively, the patient is at highest risk for dislocation if the hip is placed in which of the following positions?', '["Extension, abduction, and internal rotation", "Extension and internal rotation", "Extension and external rotation", "Flexion, adduction, and external rotation", "Flexion, abduction, and external rotation"]'::jsonb, 2, 'In a anterolateral approach to the hip, the typical position of instability causing dislocation is extension and external rotation. The Superior gluteal nerve is also at risk during this approach. Patients are routinely placed on specific hip precautions to avoid these extreme ranges of motion early in the postoperative period.'),
    (v_topic_id, 'A 84-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding myocardial infarction, which of the following is most accurate in this setting?', '["It is solely caused by the type of implant bearing surface used", "It is a rare complication seen almost exclusively in young patients", "It is completely preventable with prophylactic antibiotics", "It only occurs after the 3-month postoperative mark", "Within the first 30 days postoperatively"]'::jsonb, 4, 'Myocardial infarction is a known systemic complication following major joint arthroplasty. Specifically, it is within the first 30 days postoperatively. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 87-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding delirium, which of the following is most accurate in this setting?', '["It is completely preventable with prophylactic antibiotics", "It is solely caused by the type of implant bearing surface used", "It only occurs after the 3-month postoperative mark", "It is a rare complication seen almost exclusively in young patients", "Common in elderly patients, associated with narcotic use and hypoxia"]'::jsonb, 4, 'Delirium is a known systemic complication following major joint arthroplasty. Specifically, it is common in elderly patients, associated with narcotic use and hypoxia. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 87-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding wound dehiscence, which of the following is most accurate in this setting?', '["It is completely preventable with prophylactic antibiotics", "It is solely caused by the type of implant bearing surface used", "It is a rare complication seen almost exclusively in young patients", "Associated with early excessive flexion or poor nutrition", "It only occurs after the 3-month postoperative mark"]'::jsonb, 3, 'Wound dehiscence is a known systemic complication following major joint arthroplasty. Specifically, it is associated with early excessive flexion or poor nutrition. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 71-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is well-fixed. This is classified as Vancouver B1. What is the most appropriate management?', '["Revision arthroplasty with proximal femoral replacement", "Nonoperative management with protected weight-bearing", "ORIF with intramedullary nailing", "ORIF with plates and cables", "Revision arthroplasty with a longer stem"]'::jsonb, 3, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B1 fractures occur Around the stem, stem is well-fixed and are best managed by ORIF with plates and cables.'),
    (v_topic_id, 'A 86-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is loose. This is classified as Vancouver B2. What is the most appropriate management?', '["ORIF with plates and cables", "Revision arthroplasty with proximal femoral replacement", "Nonoperative management with protected weight-bearing", "Revision arthroplasty with a longer stem", "ORIF with intramedullary nailing"]'::jsonb, 3, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B2 fractures occur Around the stem, stem is loose and are best managed by Revision arthroplasty with a longer stem.'),
    (v_topic_id, 'A 75-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is loose. This is classified as Vancouver B2. What is the most appropriate management?', '["Nonoperative management with protected weight-bearing", "ORIF with plates and cables", "ORIF with intramedullary nailing", "Revision arthroplasty with proximal femoral replacement", "Revision arthroplasty with a longer stem"]'::jsonb, 4, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B2 fractures occur Around the stem, stem is loose and are best managed by Revision arthroplasty with a longer stem.'),
    (v_topic_id, 'A 73-year-old patient is recovering from a total hip arthroplasty. According to current guidelines for patients at standard risk for deep vein thrombosis (DVT), what is the most appropriate duration for pharmacologic VTE prophylaxis?', '["24 to 48 hours", "3 to 5 days", "3 months", "At least 10 to 14 days, up to 35 days", "6 months"]'::jsonb, 3, 'Current orthopedic guidelines recommend extending pharmacologic venous thromboembolism (VTE) prophylaxis for a minimum of 10 to 14 days, and up to 35 days, following major joint replacement surgery (THA or TKA) to minimize the risk of DVT and pulmonary embolism.'),
    (v_topic_id, 'A 68-year-old patient presents with vague, progressive shoulder pain 1 year after an anatomic total shoulder arthroplasty. Inflammatory markers are minimally elevated, and there is no frank purulence on aspiration. Intraoperative cultures eventually grow a slow-growing anaerobic Gram-positive bacillus. Which organism is most likely responsible?', '["Streptococcus pyogenes", "Staphylococcus aureus", "Pseudomonas aeruginosa", "Staphylococcus epidermidis", "Cutibacterium acnes"]'::jsonb, 4, 'Cutibacterium (formerly Propionibacterium) acnes is a common skin flora around the shoulder and a frequent cause of indolent, chronic periprosthetic joint infections following shoulder arthroplasty. It often requires prolonged incubation (up to 14 days) to grow in culture.'),
    (v_topic_id, 'A 81-year-old male undergoes a total hip arthroplasty via a standard posterior approach. Postoperatively, the patient is at highest risk for dislocation if the hip is placed in which of the following positions?', '["Flexion, adduction, and external rotation", "Extension and internal rotation", "Extension, abduction, and internal rotation", "Flexion, adduction, and internal rotation", "Flexion, abduction, and external rotation"]'::jsonb, 3, 'In a posterior approach to the hip, the typical position of instability causing dislocation is flexion, adduction, and internal rotation. The Sciatic nerve is also at risk during this approach. Patients are routinely placed on specific hip precautions to avoid these extreme ranges of motion early in the postoperative period.'),
    (v_topic_id, 'A 85-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is loose with poor bone stock. This is classified as Vancouver B3. What is the most appropriate management?', '["Revision arthroplasty with proximal femoral replacement", "Nonoperative management with protected weight-bearing", "Revision arthroplasty with a longer stem", "ORIF with plates and cables", "ORIF with intramedullary nailing"]'::jsonb, 0, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B3 fractures occur Around the stem, stem is loose with poor bone stock and are best managed by Revision arthroplasty with proximal femoral replacement.'),
    (v_topic_id, 'A 80-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is loose. This is classified as Vancouver B2. What is the most appropriate management?', '["Revision arthroplasty with a longer stem", "Nonoperative management with protected weight-bearing", "ORIF with intramedullary nailing", "Revision arthroplasty with proximal femoral replacement", "ORIF with plates and cables"]'::jsonb, 0, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B2 fractures occur Around the stem, stem is loose and are best managed by Revision arthroplasty with a longer stem.'),
    (v_topic_id, 'A 76-year-old patient complains of a ''limp'' 6 weeks after a primary total hip arthroplasty. On examination, the operative leg appears longer. What is a common intraoperative cause for lengthening the operative leg during THA?', '["Using a smaller femoral head size", "Maximizing soft tissue tension to prevent dislocation", "Excessive resection of the femoral neck", "Aggressive reaming of the acetabulum", "Placing the femoral component in varus"]'::jsonb, 1, 'Leg length discrepancy is a common patient complaint after THA. Surgeons sometimes intentionally or unintentionally lengthen the leg to increase myofascial tension (especially of the abductors) to improve hip stability and decrease the risk of dislocation.'),
    (v_topic_id, 'A 79-year-old patient is recovering from a total hip arthroplasty. According to current guidelines for patients at standard risk for deep vein thrombosis (DVT), what is the most appropriate duration for pharmacologic VTE prophylaxis?', '["3 months", "24 to 48 hours", "6 months", "3 to 5 days", "At least 10 to 14 days, up to 35 days"]'::jsonb, 4, 'Current orthopedic guidelines recommend extending pharmacologic venous thromboembolism (VTE) prophylaxis for a minimum of 10 to 14 days, and up to 35 days, following major joint replacement surgery (THA or TKA) to minimize the risk of DVT and pulmonary embolism.'),
    (v_topic_id, 'A 74-year-old patient is 8 weeks out from a primary total knee arthroplasty and complains of severe stiffness. Range of motion is 10 to 70 degrees. After failing aggressive physical therapy, what is the next most appropriate step in management?', '["Open arthrolysis and synovectomy", "Long-term casting in extension", "Arthroscopic lysis of adhesions", "Manipulation under anesthesia (MUA)", "Revision total knee arthroplasty"]'::jsonb, 3, 'Stiffness or arthrofibrosis after TKA is a frustrating complication. If aggressive physical therapy fails, the most appropriate next step within the first 2-3 months is typically a manipulation under anesthesia (MUA) to break up intra-articular adhesions and improve range of motion.'),
    (v_topic_id, 'A 72-year-old male undergoes a total hip arthroplasty via a standard anterior approach. Postoperatively, the patient is at highest risk for dislocation if the hip is placed in which of the following positions?', '["Extension, abduction, and internal rotation", "Extension and external rotation", "Extension and internal rotation", "Flexion, adduction, and external rotation", "Flexion, abduction, and external rotation"]'::jsonb, 1, 'In a anterior approach to the hip, the typical position of instability causing dislocation is extension and external rotation. The Lateral femoral cutaneous nerve is also at risk during this approach. Patients are routinely placed on specific hip precautions to avoid these extreme ranges of motion early in the postoperative period.'),
    (v_topic_id, 'A 86-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Well below the stem tip. This is classified as Vancouver C. What is the most appropriate management?', '["ORIF with plates and cables", "ORIF with plate fixation", "Nonoperative management with protected weight-bearing", "Revision arthroplasty with proximal femoral replacement", "Revision arthroplasty with a longer stem"]'::jsonb, 1, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver C fractures occur Well below the stem tip and are best managed by ORIF with plate fixation.'),
    (v_topic_id, 'A 63-year-old patient undergoes a total hip arthroplasty via an anterior approach. Postoperatively, the patient has profound weakness in knee extension and decreased sensation over the anterior thigh. Which structure was most likely injured during the procedure?', '["Sciatic nerve", "Obturator nerve", "Femoral nerve", "Superior gluteal nerve", "Lateral femoral cutaneous nerve"]'::jsonb, 2, 'The femoral nerve provides motor innervation to the quadriceps (knee extension) and sensory innervation to the anterior thigh. It can be injured during an anterior approach to the hip due to retractor placement over the anterior rim of the acetabulum.'),
    (v_topic_id, 'A 74-year-old patient presents with increasing pain in the knee 8 months after a total knee arthroplasty. Aspiration yields purulent fluid. What is the most likely responsible organism and the standard surgical management?', '["Staphylococcus epidermidis (Coagulase-negative Staph); Two-stage exchange arthroplasty", "Cutibacterium acnes; One-stage exchange arthroplasty", "Streptococcus pyogenes; Suppressive intravenous antibiotics only", "Staphylococcus aureus; Two-stage exchange arthroplasty", "Staphylococcus epidermidis; Debridement, antibiotics, and implant retention (DAIR)"]'::jsonb, 0, 'Periprosthetic joint infections present differently based on timing. Acute infections (typically < 3-4 weeks) are often caused by highly virulent organisms like Staphylococcus epidermidis (Coagulase-negative Staph) and can sometimes be managed with Two-stage exchange arthroplasty. Chronic infections are usually due to less virulent organisms like Staphylococcus epidermidis (Coagulase-negative Staph) and require a two-stage exchange.'),
    (v_topic_id, 'A 72-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is loose. This is classified as Vancouver B2. What is the most appropriate management?', '["ORIF with intramedullary nailing", "Revision arthroplasty with proximal femoral replacement", "Revision arthroplasty with a longer stem", "ORIF with plates and cables", "Nonoperative management with protected weight-bearing"]'::jsonb, 2, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B2 fractures occur Around the stem, stem is loose and are best managed by Revision arthroplasty with a longer stem.'),
    (v_topic_id, 'A 75-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding wound dehiscence, which of the following is most accurate in this setting?', '["It is a rare complication seen almost exclusively in young patients", "It only occurs after the 3-month postoperative mark", "It is completely preventable with prophylactic antibiotics", "Associated with early excessive flexion or poor nutrition", "It is solely caused by the type of implant bearing surface used"]'::jsonb, 3, 'Wound dehiscence is a known systemic complication following major joint arthroplasty. Specifically, it is associated with early excessive flexion or poor nutrition. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 78-year-old patient presents with a painful right hip and a palpable soft-tissue mass. They underwent a metal-on-metal total hip arthroplasty 10 years ago. Serum cobalt and chromium levels are elevated. What is the most likely diagnosis?', '["Adverse local tissue reaction (ALTR) / Pseudotumor", "Periprosthetic joint infection", "Aseptic loosening due to polyethylene wear", "Iliopsoas bursitis", "Heterotopic ossification"]'::jsonb, 0, 'Metal-on-metal hip implants can produce metal ion wear debris, which can trigger an adverse local tissue reaction (ALTR), often manifesting as a solid or cystic pseudotumor, pain, and elevated serum metal ions.'),
    (v_topic_id, 'A 60-year-old patient presents with vague, progressive shoulder pain 1 year after an anatomic total shoulder arthroplasty. Inflammatory markers are minimally elevated, and there is no frank purulence on aspiration. Intraoperative cultures eventually grow a slow-growing anaerobic Gram-positive bacillus. Which organism is most likely responsible?', '["Cutibacterium acnes", "Streptococcus pyogenes", "Staphylococcus aureus", "Pseudomonas aeruginosa", "Staphylococcus epidermidis"]'::jsonb, 0, 'Cutibacterium (formerly Propionibacterium) acnes is a common skin flora around the shoulder and a frequent cause of indolent, chronic periprosthetic joint infections following shoulder arthroplasty. It often requires prolonged incubation (up to 14 days) to grow in culture.'),
